interface IStructs {
    enum ProductCategory { DryGoods, Perishable, Hazmat, Bulk, RawMaterial, WIP, FinishedGood, MRO, Packaging }
    enum ProductStatus { Created, InTransit, Stored, Delivered, Consumed, Spoiled }

