        string name;
        string serialNumber;
        string batchNumber;
        ProductCategory category;
        uint256 quantity;
        uint256 unitCost;
        uint256 expiryDate;
        bool requiresTemperatureControl;
        int256 minTemperature;
        int256 maxTemperature;
    }
}

